import { cn } from "@/lib/utils"

/**
 * Total Wireless Line Counter Component
 *
 * The +/- counter for selecting number of phone lines.
 * Prominent in the plan selection page.
 *
 * Usage:
 * <LineCounter value={1} min={1} max={5} onChange={setLines} />
 */

interface LineCounterProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  value: number
  min?: number
  max?: number
  onChange?: (value: number) => void
}

function LineCounter({
  className,
  value,
  min = 1,
  max = 5,
  onChange,
  ...props
}: LineCounterProps) {
  return (
    <div
      data-slot="line-counter"
      className={cn(
        "inline-flex h-11 items-center gap-2 rounded-full border border-tw-gray-300 bg-white px-1 shadow-[0_1px_2px_rgba(16,24,40,0.05)]",
        className
      )}
      {...props}
    >
      <button
        type="button"
        onClick={() => onChange?.(Math.max(min, value - 1))}
        disabled={value <= min}
        className={cn(
          "flex size-8 items-center justify-center rounded-full border border-transparent transition-all cursor-pointer",
          value <= min
            ? "text-tw-gray-400"
            : "text-tw-navy-900 hover:bg-[var(--tw-button-hover-muted)] active:bg-tw-gray-100"
        )}
        aria-label="Decrease lines"
      >
        <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 12h14" />
        </svg>
      </button>

      <span className="min-w-8 text-center text-base font-bold leading-6 text-tw-navy-900">
        {value}
      </span>

      <button
        type="button"
        onClick={() => onChange?.(Math.min(max, value + 1))}
        disabled={value >= max}
        className={cn(
          "flex size-8 items-center justify-center rounded-full border border-transparent transition-all cursor-pointer",
          value >= max
            ? "text-tw-gray-400"
            : "text-tw-navy-900 hover:bg-[var(--tw-button-hover-muted)] active:bg-tw-gray-100"
        )}
        aria-label="Increase lines"
      >
        <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
        </svg>
      </button>
    </div>
  )
}

export { LineCounter }
export type { LineCounterProps }
